CREATE TABLE public.website_content (key text PRIMARY KEY, value text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.website_content TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_content TO authenticated;
GRANT ALL ON public.website_content TO service_role;
ALTER TABLE public.website_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published website content" ON public.website_content FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Staff manage website content" ON public.website_content FOR ALL TO authenticated USING (private.is_staff(auth.uid())) WITH CHECK (private.is_staff(auth.uid()));
CREATE TABLE public.website_drafts (key text PRIMARY KEY, value text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_drafts TO authenticated;
GRANT ALL ON public.website_drafts TO service_role;
ALTER TABLE public.website_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff manage website drafts" ON public.website_drafts FOR ALL TO authenticated USING (private.is_staff(auth.uid())) WITH CHECK (private.is_staff(auth.uid()));
CREATE TABLE public.website_offerings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category text NOT NULL DEFAULT 'birthday', name text NOT NULL, description text NOT NULL DEFAULT '', price_cents integer NOT NULL DEFAULT 0 CHECK (price_cents>=0 AND price_cents<=10000000), pricing_note text NOT NULL DEFAULT '', capacity text NOT NULL DEFAULT '', value_note text NOT NULL DEFAULT '', tag text NOT NULL DEFAULT '', features text[] NOT NULL DEFAULT '{}', note text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT false, is_archived boolean NOT NULL DEFAULT false, verified boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT offering_category CHECK (category IN ('birthday','party-lanes','rental')), CONSTRAINT offering_name CHECK (length(trim(name)) BETWEEN 1 AND 150));
GRANT SELECT ON public.website_offerings TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.website_offerings TO authenticated;
GRANT ALL ON public.website_offerings TO service_role;
ALTER TABLE public.website_offerings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public published offerings" ON public.website_offerings FOR SELECT TO anon, authenticated USING (is_active AND NOT is_archived AND verified);
CREATE POLICY "Staff manage offerings" ON public.website_offerings FOR ALL TO authenticated USING (private.is_staff(auth.uid())) WITH CHECK (private.is_staff(auth.uid()));
ALTER TABLE public.events ADD COLUMN IF NOT EXISTS is_archived boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS image_url text;
ALTER TABLE public.announcements ADD COLUMN IF NOT EXISTS is_archived boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS image_url text, ADD COLUMN IF NOT EXISTS featured boolean NOT NULL DEFAULT true;
ALTER POLICY "Events are public" ON public.events USING (is_active AND NOT is_archived AND (end_date IS NULL OR end_date >= current_date));
ALTER POLICY "Announcements are public" ON public.announcements USING (is_active AND NOT is_archived AND (starts_on IS NULL OR starts_on <= current_date) AND (ends_on IS NULL OR ends_on >= current_date));
ALTER POLICY "Leagues are public" ON public.leagues USING (is_active);
ALTER POLICY "Pricing is public" ON public.pricing_items USING (is_active);
ALTER POLICY "Seasonal hour schedules are public" ON public.seasonal_hour_schedules USING (is_active);
ALTER POLICY "Seasonal hours are public" ON public.seasonal_hours USING (EXISTS (SELECT 1 FROM public.seasonal_hour_schedules s WHERE s.id = schedule_id AND s.is_active));
CREATE FUNCTION public.website_publish(p_keys text[]) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN IF NOT private.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Staff only'; END IF; INSERT INTO public.website_content(key,value) SELECT key,value FROM public.website_drafts WHERE key=ANY(p_keys) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=now(); DELETE FROM public.website_drafts WHERE key=ANY(p_keys); END $$;
REVOKE ALL ON FUNCTION public.website_publish(text[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.website_publish(text[]) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.submit_event_inquiry(jsonb) FROM anon, authenticated;
COMMENT ON FUNCTION public.submit_event_inquiry(jsonb) IS 'Retired public submission: telephone-only. Staff inquiries use reservation_inquiry_save.';